namespace AIFrontend.Pages.OpenCode;

/// <summary>Installed for future documents and injected once more on activation. Never changes page content.</summary>
internal static class OpenCodeBrowserSelectionScript
{
    internal const string Source = """
(() => {
 if(window.__aifSelection) return;
 let mode='None', nonce='', start=null, shapes=[], current=null, selected=[], draft=null, savedDraft=null, candidateCache=null, draftKey='', draftNumber=0, lastScrollX=scrollX, lastScrollY=scrollY;
 let pen='pen', color='#F43F5E', note='', host, canvas, ctx, hover, label;
  const send=(type,data={})=>window.__aifSelectionSend(JSON.stringify({aifSelection:nonce,type,...data}));
 const rect=(a,b,square=false)=>{let dx=b.x-a.x,dy=b.y-a.y;if(square){let s=Math.max(Math.abs(dx),Math.abs(dy));dx=Math.sign(dx||1)*s;dy=Math.sign(dy||1)*s;}return{x:Math.min(a.x,a.x+dx),y:Math.min(a.y,a.y+dy),width:Math.abs(dx),height:Math.abs(dy)}};
 const point=e=>({x:e.clientX,y:e.clientY});
 const corners=r=>[{x:r.x,y:r.y},{x:r.x+r.width,y:r.y},{x:r.x+r.width,y:r.y+r.height},{x:r.x,y:r.y+r.height}];
 const selector=e=>{if(e.id)return '#'+CSS.escape(e.id);let parts=[];while(e&&e!==document.documentElement){let n=e.localName;if(!n)break;let parent=e.parentElement;if(parent){let peers=[...parent.children].filter(x=>x.localName===n);if(peers.length>1)n+=':nth-of-type('+(peers.indexOf(e)+1)+')'}parts.unshift(n);e=parent;}return 'html > '+parts.join(' > ')};
 const candidates=box=>(candidateCache??=[...document.querySelectorAll('body *')].filter(e=>!host.contains(e)&&!['SCRIPT','STYLE','LINK','META','NOSCRIPT'].includes(e.tagName)).map(e=>({e,r:e.getBoundingClientRect()})).filter(({e,r})=>r.width>0&&r.height>0&&getComputedStyle(e).visibility!=='hidden'&&r.x>=0&&r.y>=0&&r.right<=innerWidth&&r.bottom<=innerHeight)).filter(({r})=>corners(r).every(p=>p.x>=box.x&&p.y>=box.y&&p.x<=box.x+box.width&&p.y<=box.y+box.height)).map(({e,r})=>({selector:selector(e),box:{x:r.x,y:r.y,width:r.width,height:r.height}}));
 function ensure(){if(host?.isConnected)return;host=document.createElement('div');host.dataset.aifSelection='';host.style.cssText='all:initial;position:fixed;inset:0;z-index:2147483647;pointer-events:none;';let shadow=host.attachShadow({mode:'closed'});canvas=document.createElement('canvas');canvas.style.cssText='width:100%;height:100%;position:absolute;inset:0;';shadow.append(canvas);hover=document.createElement('div');hover.style.cssText='position:absolute;border:2px solid #38BDF8;box-sizing:border-box;display:none;';shadow.append(hover);label=document.createElement('div');label.style.cssText='position:absolute;background:#1d4ed8;color:white;font:12px monospace;padding:4px 7px;border-radius:3px;white-space:nowrap;display:none;';shadow.append(label);(document.documentElement||document).append(host);ctx=canvas.getContext('2d');resize();}
 function resize(){if(!canvas)return;canvas.width=innerWidth*devicePixelRatio;canvas.height=innerHeight*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);draw()}
 function shape(s){ctx.strokeStyle=s.color;ctx.fillStyle=s.color;ctx.lineWidth=3;ctx.setLineDash([]);if(s.pen==='note'){ctx.beginPath();ctx.arc(s.a.x,s.a.y,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='white';ctx.font='12px sans-serif';ctx.fillText(String(s.number),s.a.x-4,s.a.y+4);ctx.fillStyle=s.color;ctx.fillText(s.note,s.a.x+16,s.a.y+4)}else if(s.pen==='rectangle'){let r=rect(s.a,s.b);ctx.strokeRect(r.x,r.y,r.width,r.height)}else{ctx.beginPath();if(s.pen==='pen'){s.points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y))}else{ctx.moveTo(s.a.x,s.a.y);ctx.lineTo(s.b.x,s.b.y);let t=Math.atan2(s.b.y-s.a.y,s.b.x-s.a.x);ctx.moveTo(s.b.x-14*Math.cos(t-.45),s.b.y-14*Math.sin(t-.45));ctx.lineTo(s.b.x,s.b.y);ctx.lineTo(s.b.x-14*Math.cos(t+.45),s.b.y-14*Math.sin(t+.45))}ctx.stroke()}}
  function draw(){if(!ctx)return;ctx.clearRect(0,0,innerWidth,innerHeight);for(let s of selected){let r=s.selector?document.querySelector(s.selector)?.getBoundingClientRect()||s.box:s.box;ctx.strokeStyle=s.color;ctx.lineWidth=2;ctx.setLineDash([]);ctx.strokeRect(r.x,r.y,r.width,r.height);ctx.fillStyle=s.color;ctx.fillRect(r.x,r.y,20,20);ctx.fillStyle='white';ctx.font='12px sans-serif';ctx.fillText(s.number,r.x+4,r.y+14)}
 if(draft){let r=draft.box;ctx.fillStyle='rgba(0,0,0,.35)';ctx.beginPath();ctx.rect(0,0,innerWidth,innerHeight);ctx.rect(r.x,r.y,r.width,r.height);ctx.fill('evenodd');ctx.strokeStyle='white';ctx.lineWidth=2;ctx.setLineDash([6,4]);ctx.strokeRect(r.x,r.y,r.width,r.height);ctx.setLineDash([]);for(let p of corners(r)){ctx.fillStyle='white';ctx.fillRect(p.x-4,p.y-4,8,8)}for(let e of draft.elements||[]){let q=e.box;ctx.strokeStyle='#38BDF8';ctx.strokeRect(q.x,q.y,q.width,q.height)}ctx.fillStyle='#111827';ctx.fillRect(Math.max(0,r.x),Math.max(0,r.y-27),300,24);ctx.fillStyle='white';ctx.font='12px sans-serif';ctx.fillText(Math.round(r.width)+' × '+Math.round(r.height)+' · 包含 '+(draft.elements?.length??0)+' 个元素',Math.max(4,r.x+4),Math.max(17,r.y-10));}
 for(let s of shapes)shape(s);if(current)shape(current);}
  function move(e){if(mode==='None'||mode==='Element')return;let p=point(e);if(start){if(mode==='Region'||mode==='Screenshot'){let r=rect(start,p,e.shiftKey);draft={box:r,elements:candidates(r)}}else if(mode==='Annotate'){current.b=p;current.points.push(p)}draw();return;}}
   function down(e){if(mode==='None'||mode==='Element'||e.button!==0)return;e.preventDefault();e.stopImmediatePropagation();candidateCache=null;let p=point(e),handle=-1;if(draft&&(mode==='Region'||mode==='Screenshot'))handle=corners(draft.box).findIndex(q=>Math.hypot(q.x-p.x,q.y-p.y)<=9);if(handle>=0)start=corners(draft.box)[(handle+2)%4];else{start=p;draftKey=String(++draftNumber);draft=null}hover.style.display=label.style.display='none';if(mode==='Annotate')current={pen,color,note,a:start,b:start,points:[start],number:shapes.filter(s=>s.pen==='note').length+1};}
   function up(e){if(mode==='None'||mode==='Element'||e.button!==0)return;e.preventDefault();e.stopImmediatePropagation();if(!start)return;start=null;if(mode==='Annotate'){shapes.push(current);current=null;draw();return}if(draft&&draft.box.width>=1&&draft.box.height>=1)send('region',{key:draftKey,box:draft.box,selectors:draft.elements.map(e=>e.selector),kind:mode});}
  for(let event of ['click','dblclick','contextmenu'])document.addEventListener(event,e=>{if(mode!=='None'&&mode!=='Element'){e.preventDefault();e.stopImmediatePropagation()}},true);
 document.addEventListener('pointerdown',down,true);document.addEventListener('pointermove',move,true);document.addEventListener('pointerup',up,true);
  document.addEventListener('keydown',e=>{if(mode!=='None'){send('modifier',{multi:e.shiftKey});if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();send('escape')}}},true);
  document.addEventListener('keyup',e=>{if(mode!=='None')send('modifier',{multi:e.shiftKey})},true);
  addEventListener('resize',()=>{candidateCache=null;resize()});addEventListener('scroll',()=>{if(mode!=='None'){draft=null;candidateCache=null;for(let s of selected){s.box.x-=scrollX-lastScrollX;s.box.y-=scrollY-lastScrollY}lastScrollX=scrollX;lastScrollY=scrollY;send('scrolled');draw()}},true);
   // Native inspect ignores pointer-events:none while Shift is held. Keep our canvas out of its hit test.
   window.__aifSelection={activate(m,n){ensure();mode=m;nonce=n;start=null;draft=null;candidateCache=null;host.style.display=m==='None'||m==='Element'?'none':'block';host.style.pointerEvents=m==='Region'||m==='Screenshot'||m==='Annotate'?'auto':'none';hover.style.display=label.style.display='none';if(m!=='Annotate')shapes=[];draw()},settings(p,c,t){pen=p;color=c;note=t},undo(){shapes.pop();draw()},clearDraft(){draft=null;draw()},selected(items){selected=items||[];draw()},capture(annotations){host.style.display=annotations?'block':'none';hover.style.display=label.style.display='none';savedDraft=draft;draft=null;let old=selected;selected=[];draw();selected=old},restore(){draft=savedDraft;host.style.display=mode==='None'||mode==='Element'?'none':'block';draw()},finish(){return shapes.filter(s=>s.pen==='note').map(s=>s.number+'. '+s.note).join('\n')}};
})();
""";
    internal const string Candidates = """
(() => {
 const selector=e=>{let parts=[];while(e&&e!==document.documentElement){let n=e.localName;if(e.id){parts.unshift('#'+CSS.escape(e.id));break}let p=e.parentElement;if(p){let peers=[...p.children].filter(x=>x.localName===n);if(peers.length>1)n+=':nth-of-type('+(peers.indexOf(e)+1)+')'}parts.unshift(n);e=p}return parts.join(' > ')};
 return [...document.querySelectorAll('body *')].filter(e=>!e.closest('[data-aif-selection]')&&!['SCRIPT','STYLE','LINK','META','NOSCRIPT'].includes(e.tagName))
  .map(e=>({e,r:e.getBoundingClientRect()})).filter(({e,r})=>r.width>0&&r.height>0&&r.right>0&&r.bottom>0&&r.x<innerWidth&&r.y<innerHeight&&getComputedStyle(e).visibility!=='hidden')
  .map(({e,r})=>({selector:selector(e),x:r.x,y:r.y,width:r.width,height:r.height}));
})()
""";
